use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::BTreeMap;

const BILLING_INCREMENT_SECONDS: i64 = 15 * 60;
const BILLING_MINIMUM_SECONDS: i64 = 30 * 60;

pub struct MonthlyInvoiceCommand;

fn billed_seconds(entry: &TimeEntry) -> i64 {
    let duration = entry.duration.max(0);
    let rounded = ((duration + BILLING_INCREMENT_SECONDS - 1) / BILLING_INCREMENT_SECONDS)
        * BILLING_INCREMENT_SECONDS;
    rounded.max(BILLING_MINIMUM_SECONDS)
}

fn aggregate_months(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
    let mut months = BTreeMap::new();
    for entry in entries
        .iter()
        .filter(|entry| entry.billable && entry.stop.is_some())
    {
        let month = entry.start.format("%Y-%m").to_string();
        *months.entry(month).or_insert(0) += billed_seconds(entry);
    }
    months
}

impl MonthlyInvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let months = aggregate_months(&entries);

        if months.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = months.values().sum();
        for (month, seconds) in &months {
            println!("{month}  {seconds}s");
        }
        println!("Total  {total}s");
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{TimeZone, Utc};

    fn entry(start: &str, duration: i64, billable: bool, stopped: bool) -> TimeEntry {
        TimeEntry {
            id: 1,
            description: String::new(),
            start: Utc.datetime_from_str(start, "%Y-%m-%dT%H:%M:%SZ").unwrap(),
            stop: stopped.then(|| Utc.timestamp_opt(1_700_000_000, 0).single().unwrap()),
            duration,
            billable,
            workspace_id: 1,
            tags: Vec::new(),
            project: None,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn aggregates_stopped_billable_entries_by_utc_month_oldest_first() {
        let entries = vec![
            entry("2026-02-01T00:00:00Z", 901, true, true),
            entry("2026-01-31T23:00:00Z", 1, true, true),
            entry("2026-02-03T00:00:00Z", 3600, false, true),
            entry("2026-01-15T00:00:00Z", 3600, true, false),
        ];

        assert_eq!(
            aggregate_months(&entries).into_iter().collect::<Vec<_>>(),
            vec![("2026-01".to_string(), 1800), ("2026-02".to_string(), 1800)]
        );
    }

    #[test]
    fn applies_rounding_and_per_entry_minimum() {
        let entries = vec![
            entry("2026-01-01T00:00:00Z", 900, true, true),
            entry("2026-01-01T01:00:00Z", 901, true, true),
        ];
        assert_eq!(aggregate_months(&entries)["2026-01"], 3600);
    }
}
